package com.example.bandlink.controller; import com.example.bandlink.dto.AdminReportResponse; import com.example.bandlink.entity.ReportStatus; import com.example.bandlink.repository.ReportRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/reports") public class AdminReportController{private final ReportRepository reports;public AdminReportController(ReportRepository r){reports=r;}@GetMapping public List<AdminReportResponse> list(@RequestParam(defaultValue="PENDING") ReportStatus status){return reports.findByStatusOrderByCreatedAtAsc(status).stream().map(AdminReportResponse::from).toList();}@PatchMapping("/{id}") public AdminReportResponse update(@PathVariable Long id,@RequestParam ReportStatus status){var r=reports.findById(id).orElseThrow();r.setStatus(status);return AdminReportResponse.from(reports.save(r));}}
